begin;
set local search_path=public,extensions;
select no_plan();
select ok(not has_table_privilege('anon','public.pulse_schedule_notices','SELECT,INSERT,UPDATE,DELETE'),'no anonymous raw notice access');
select ok(not has_function_privilege('anon','public.send_public_pulse_notice(uuid,text,uuid,boolean)','EXECUTE'),'public viewer cannot send');
select set_config('realtime.topic','pulse-schedule-notices-v1',true);
insert into realtime.messages(topic,extension,event,payload,private) values('pulse-schedule-notices-v1','broadcast','notice','{"test":true}',true);
set local role anon;
select is(jsonb_array_length(public.get_public_pulse_schedule()->'events'),5,'schedule opens anonymously with all five configured events');
select ok(not(public.get_public_pulse_schedule() ? 'agents'),'no Agent roster in public schedule');
select lives_ok($$select * from realtime.messages where topic='pulse-schedule-notices-v1'$$,'anonymous private-channel read requires no account');
select throws_ok($$insert into realtime.messages(topic,extension,event,payload,private) values('pulse-schedule-notices-v1','broadcast','notice','{}',true)$$,'42501',null,'anonymous browser cannot forge notice broadcasts');
select throws_ok($$select public.list_public_pulse_notices()$$,'42501',null,'public viewer cannot read Admin history');
select is(public.get_public_pulse_notice('a1110000-0000-4000-8000-000000000001'),null::jsonb,'untrusted invented ID is not an alarm');
reset role;
insert into auth.users(id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at) values('e1140000-0000-4000-8000-000000000001','authenticated','authenticated','public.schedule.master@example.test','',now(),'{}','{}',now(),now());
insert into public.users(id,auth_user_id,email,full_name,status,approved_at) values('f1140000-0000-4000-8000-000000000001','e1140000-0000-4000-8000-000000000001','public.schedule.master@example.test','Synthetic Schedule Admin','active',now());
insert into public.user_roles(user_id,role_id,scope_type) select 'f1140000-0000-4000-8000-000000000001',id,'global' from public.roles where key='super_admin';
select set_config('request.jwt.claim.sub','e1140000-0000-4000-8000-000000000001',true);
set local role authenticated;
select throws_ok($$select public.send_public_pulse_notice('a1120000-0000-4000-8000-000000000002','start','a1140000-0000-4000-8000-000000000001',false)$$,'22023',null,'even Admin must confirm audience');
select lives_ok($$select public.send_public_pulse_notice('a1120000-0000-4000-8000-000000000002','start','a1140000-0000-4000-8000-000000000001',true)$$,'Admin can send manually');
select lives_ok($$select public.send_public_pulse_notice('a1120000-0000-4000-8000-000000000002','start','a1140000-0000-4000-8000-000000000001',true)$$,'same request retries without another broadcast');
select throws_ok($$select public.send_public_pulse_notice('a1120000-0000-4000-8000-000000000002','start','a1140000-0000-4000-8000-000000000002',true)$$,'55000',null,'consecutive accidental sends are limited');
select is(jsonb_array_length(public.list_public_pulse_notices()),1,'Admin sees a simple sent history');
reset role;
select is((select count(*) from public.agents),0::bigint,'no Agents created or required');
select is((select count(*) from public.pulse_alert_deliveries),0::bigint,'public recipients have no per-Agent delivery tracking');
set local role anon;
select ok(not(public.get_public_pulse_notice((public.get_current_public_pulse_notices()->0->>'occurrence_id')::uuid) ? 'sent_by'),'public payload excludes sender identity');
select is(public.get_public_pulse_notice((public.get_current_public_pulse_notices()->0->>'occurrence_id')::uuid)->'payload'->>'phase','start','anonymous viewer resolves verified server message');
reset role;
update public.pulse_schedule_notices set expires_at=clock_timestamp()-interval '40 minutes' where request_id='a1140000-0000-4000-8000-000000000001';
set local role anon;
select is(jsonb_array_length(public.get_current_public_pulse_notices()),0,'no stale catch-up alarm');
reset role;
select * from finish();
rollback;
